import numpy as np

def mse_loss(y_true, y_pred):
    return np.mean((y_true - y_pred)**2)

y_true = np.array([3, -0.5, 2, 7])
y_pred = np.array([2.5, 0.0, 2, 8])
print(f"MSE Loss: {mse_loss(y_true, y_pred)}")

import numpy as np

def gradient_descent(start_x, learning_rate, epochs):
    x = start_x
    for i in range(epochs):
        grad = 2 * x  # derivative of x^2
        x = x - learning_rate * grad
        if i % 5 == 0:
            print(f"Epoch {i}: x = {x:.4f}, loss = {x**2:.4f}")
    return x

final_min = gradient_descent(start_x=10, learning_rate=0.1, epochs=25)
